mapper.select:
select t.floor_id,t.floor_id floorId,t.machine_id,t.machine_id machineId,t.unit_id,t.unit_id
unitId,t.unit_num,t.unit_num unitNum,t.acf_id,t.acf_id acfId,t.status_cd,t.status_cd
statusCd,t.community_id,t.community_id communityId,t.floor_num,t.floor_num floorNum,
ac.machine_code machineCode,ac.machine_name machineName,t.create_time createTime
from access_control_floor t
left join access_control ac on ac.machine_id = t.machine_id and ac.status_cd = '0'
where 1 =1

    and t.floor_id= #{floorId}


    and t.machine_id= #{machineId}


    and t.unit_id= #{unitId}


    and t.unit_num= #{unitNum}


    and t.acf_id= #{acfId}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.floor_num= #{floorNum}

order by t.create_time desc

    limit #{page}, #{row}

